using System.Reflection;
using System.Text.Json;
using MSUIClient.Formats;

namespace MSUIClient.Creator.Spells;

// ═══════════════════════════════════════════════════════════════════════════
// SPELL LEGALITY — "feasible within the rules of the vanilla world" as a check, not a feeling
// (shared_docs/SPELL_CREATOR_PLAN.md §2 rule 2, P1.2).
//
// The data is Data/vanilla-spell-rules.json, generated by tools/spellvis/spell_rules_extract.py
// from the Core's own handler tables and the stock Spell.dbc: which effects and auras this
// server actually implements, every implicit target it knows, and every effect/aura/target
// combination Blizzard's 1.12 spells use (with how often and an example). The law:
//
//   ERROR    an effect or aura with no handler (the server does nothing), an unknown target id,
//            an index (cast time, duration, range, radius) with no row, a trigger spell that
//            does not exist - the spell cannot work as authored;
//   WARNING  a combination no stock spell uses, a flag with no effect (deferred destination on
//            a spell that is not a ground missile), an area target with no radius;
//   INFO     what the closest real spells do ("used by 381 stock spells, e.g. #10").
//
// Pure: values in, lines out.
// ═══════════════════════════════════════════════════════════════════════════
public static class SpellLegality
{
    public const string ResourceName = "MSUIClient.Data.vanilla-spell-rules.json";

    public enum Severity { Info, Warning, Error }

    public readonly record struct Line(Severity Severity, string Field, string Message);

    public sealed record Entry(int Id, string Name, string Handler, bool Implemented, int Uses, string Note)
    {
        /// <summary>"SCHOOL_DAMAGE" from SPELL_EFFECT_SCHOOL_DAMAGE; readable fallback when unnamed.</summary>
        public string Short(string prefix) =>
            Name.Length == 0 ? $"#{Id}" : Name.StartsWith(prefix, StringComparison.Ordinal) ? Name[prefix.Length..] : Name;
    }

    public sealed record Combo(int Effect, int Aura, int A, int B, int Uses, int Example);

    public sealed class Data
    {
        public required IReadOnlyList<Entry> Effects { get; init; }
        public required IReadOnlyList<Entry> Auras { get; init; }
        public required IReadOnlyList<Entry> Targets { get; init; }
        public required IReadOnlyDictionary<(int, int, int, int), Combo> Combos { get; init; }
        public required IReadOnlySet<int> AuraEffects { get; init; }
        public required string CoreHead { get; init; }

        public Entry? Effect(int id) => id >= 0 && id < Effects.Count ? Effects[id] : null;
        public Entry? Aura(int id) => id >= 0 && id < Auras.Count ? Auras[id] : null;
        public Entry? Target(int id) => Targets.FirstOrDefault(t => t.Id == id);

        public string EffectName(int id) => Effect(id)?.Short("SPELL_EFFECT_") ?? $"#{id}";
        public string AuraName(int id) => Aura(id)?.Short("SPELL_AURA_") ?? $"#{id}";
        public string TargetName(int id) => id == 0 ? "none" : Target(id)?.Short("TARGET_") ?? $"#{id}";
    }

    private static Data? _data;

    /// <summary>The embedded table, parsed once.</summary>
    public static Data Load()
    {
        if (_data is not null) return _data;
        using Stream stream = Assembly.GetExecutingAssembly().GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"{ResourceName} is not embedded");
        using JsonDocument doc = JsonDocument.Parse(stream);
        JsonElement root = doc.RootElement;
        static List<Entry> Entries(JsonElement list) => list.EnumerateArray().Select(e => new Entry(
            e.GetProperty("id").GetInt32(),
            e.TryGetProperty("name", out var n) ? n.GetString() ?? "" : "",
            e.TryGetProperty("handler", out var h) ? h.GetString() ?? "" : "",
            !e.TryGetProperty("implemented", out var i) || i.GetBoolean(),
            e.TryGetProperty("uses", out var u) ? u.GetInt32() : 0,
            e.TryGetProperty("note", out var no) ? no.GetString() ?? "" : "")).ToList();
        var combos = new Dictionary<(int, int, int, int), Combo>();
        foreach (JsonElement c in root.GetProperty("combos").EnumerateArray())
        {
            var combo = new Combo(c.GetProperty("effect").GetInt32(), c.GetProperty("aura").GetInt32(),
                c.GetProperty("a").GetInt32(), c.GetProperty("b").GetInt32(),
                c.GetProperty("uses").GetInt32(), c.GetProperty("example").GetInt32());
            combos[(combo.Effect, combo.Aura, combo.A, combo.B)] = combo;
        }
        _data = new Data
        {
            Effects = Entries(root.GetProperty("effects")),
            Auras = Entries(root.GetProperty("auras")),
            Targets = Entries(root.GetProperty("targets")),
            Combos = combos,
            AuraEffects = root.GetProperty("auraEffects").EnumerateArray().Select(x => x.GetInt32()).ToHashSet(),
            CoreHead = root.TryGetProperty("coreHead", out var head) ? head.GetString() ?? "" : "",
        };
        return _data;
    }

    /// <summary>Implicit targets that put the effect's units AT the destination (or the ground
    /// itself) - the ones a ground cast needs and a radius matters for.</summary>
    public static readonly IReadOnlySet<int> DestinationTargets = new HashSet<int> { 8, 16, 17, 18, 28, 31, 34, 53, 63 };

    /// <summary>Implicit targets that hit an AREA (a radius is meaningful).</summary>
    public static readonly IReadOnlySet<int> AreaTargets = new HashSet<int> { 2, 3, 4, 8, 15, 16, 20, 22, 24, 28, 29, 30, 31, 33, 34, 37, 54, 56, 61 };

    public static List<Line> Validate(SpellRules rules, SpellRuleTables? tables, Func<uint, bool>? spellExists = null)
    {
        Data data = Load();
        var lines = new List<Line>();
        void Add(Severity s, string field, string message) => lines.Add(new Line(s, field, message));

        // Indices point at real rows.
        if (tables is not null)
        {
            uint cast = (uint)rules.GetInt("castingTimeIndex");
            if (cast != 0 && !tables.CastTimes.ContainsKey(cast))
                Add(Severity.Error, "castingTimeIndex", $"cast time row {cast} does not exist");
            uint duration = (uint)rules.GetInt("durationIndex");
            if (duration != 0 && !tables.Durations.ContainsKey(duration))
                Add(Severity.Error, "durationIndex", $"duration row {duration} does not exist");
            uint range = (uint)rules.GetInt("rangeIndex");
            if (!tables.Ranges.ContainsKey(range))
                Add(Severity.Error, "rangeIndex", $"range row {range} does not exist");
        }

        bool anyDestination = false, anyEffect = false;
        for (int e = 1; e <= 3; e++)
        {
            int type = rules.EffectType(e);
            if (type == 0) continue;
            anyEffect = true;
            string field = SpellRules.Column("effect", e);
            Entry? effect = data.Effect(type);
            if (effect is null) { Add(Severity.Error, field, $"effect {e}: type {type} does not exist (0..133)"); continue; }
            if (!effect.Implemented)
                Add(Severity.Error, field, $"effect {e}: {data.EffectName(type)} has no handler on this server - it does nothing");

            int aura = data.AuraEffects.Contains(type) ? rules.EffectAura(e) : 0;
            if (data.AuraEffects.Contains(type))
            {
                Entry? auraEntry = data.Aura(aura);
                if (aura == 0) Add(Severity.Error, SpellRules.Column("effectApplyAuraName", e), $"effect {e}: {data.EffectName(type)} needs an aura");
                else if (auraEntry is null) Add(Severity.Error, SpellRules.Column("effectApplyAuraName", e), $"effect {e}: aura {aura} does not exist (0..192)");
                else if (!auraEntry.Implemented)
                    Add(Severity.Error, SpellRules.Column("effectApplyAuraName", e), $"effect {e}: aura {data.AuraName(aura)} has no handler on this server");
            }

            int a = rules.GetInt(SpellRules.Column("effectImplicitTargetA", e));
            int b = rules.GetInt(SpellRules.Column("effectImplicitTargetB", e));
            foreach ((int t, string tf) in new[] { (a, "effectImplicitTargetA"), (b, "effectImplicitTargetB") })
                if (t != 0 && data.Target(t) is null)
                    Add(Severity.Error, SpellRules.Column(tf, e), $"effect {e}: target {t} is not a target this server knows");
            if (DestinationTargets.Contains(a) || DestinationTargets.Contains(b)) anyDestination = true;

            uint radius = (uint)rules.GetInt(SpellRules.Column("effectRadiusIndex", e));
            if (tables is not null && radius != 0 && !tables.Radii.ContainsKey(radius))
                Add(Severity.Error, SpellRules.Column("effectRadiusIndex", e), $"effect {e}: radius row {radius} does not exist");
            if ((AreaTargets.Contains(a) || AreaTargets.Contains(b)) && radius == 0)
                Add(Severity.Warning, SpellRules.Column("effectRadiusIndex", e), $"effect {e}: an area target with no radius hits nothing");

            int trigger = rules.GetInt(SpellRules.Column("effectTriggerSpell", e));
            if (trigger != 0 && spellExists is not null && !spellExists((uint)trigger))
                Add(Severity.Error, SpellRules.Column("effectTriggerSpell", e), $"effect {e}: trigger spell {trigger} does not exist");

            if (data.Combos.TryGetValue((type, aura, a, b), out Combo? combo))
                Add(Severity.Info, field, $"effect {e}: {Describe(data, type, aura, a, b)} - used by {combo.Uses} stock spell(s), e.g. #{combo.Example}");
            else
                Add(Severity.Warning, field, $"effect {e}: no stock spell uses {Describe(data, type, aura, a, b)} - it may still work, nothing proves it does");
        }
        if (!anyEffect) Add(Severity.Warning, "effect1", "the spell has no effect - it will cast and do nothing");

        if (rules.GroundTargeted && !anyDestination)
            Add(Severity.Warning, "targets", "ground-targeted, but no effect targets the destination (16 enemies there, 18 the point, 28 a persistent area)");
        if (!rules.GroundTargeted && anyDestination && !lines.Any(l => l.Field.StartsWith("effectImplicitTarget", StringComparison.Ordinal)))
            Add(Severity.Info, "targets", "an effect targets a destination but the player does not pick one: it will use the caster's or the target's position");
        if (rules.Deferred && !(rules.GroundTargeted && rules.Speed > 0f))
            Add(Severity.Warning, "customFlags", "deferred destination only acts on a ground-targeted spell with a missile speed");
        return lines;
    }

    public static string Describe(Data data, int effect, int aura, int a, int b) =>
        data.EffectName(effect) + (aura != 0 ? $"({data.AuraName(aura)})" : "") +
        $" @ {data.TargetName(a)}" + (b != 0 ? $"/{data.TargetName(b)}" : "");
}
